fn frame(t: i32) {
    let w: i32 = host::display::width();
    let tx: i32 = 30;
    let tw: i32 = w - 60;
    let ty: i32 = 130;
    if host::display::state_get(5) == 0 {
        host::display::state_set(5, 1);
        host::display::state_set(0, 20);
        host::display::state_set(1, 80);
    }
    let mut lo: i32 = host::display::state_get(0);
    let mut hi: i32 = host::display::state_get(1);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(3);
    let px: i32 = host::display::pointer_x();
    let mut grab: i32 = host::display::state_get(2);
    let mut rel: i32 = (px - tx) * 100 / tw;
    if rel < 0 { rel = 0; }
    if rel > 100 { rel = 100; }
    if down == 1 && prev == 0 {
        let dl: i32 = if rel > lo { rel - lo } else { lo - rel };
        let dh: i32 = if rel > hi { rel - hi } else { hi - rel };
        grab = if dl <= dh { 1 } else { 2 };
        host::display::state_set(2, grab);
    }
    if down == 0 {
        grab = 0;
        host::display::state_set(2, 0);
    }
    if grab == 1 {
        lo = rel;
        if lo > hi { lo = hi; }
        host::display::state_set(0, lo);
    }
    if grab == 2 {
        hi = rel;
        if hi < lo { hi = lo; }
        host::display::state_set(1, hi);
    }
    host::display::state_set(3, down);
    host::display::clear(0x101010);
    host::display::fill_rect(tx, ty, tw, 4, 0x404040);
    let lx: i32 = tx + lo * tw / 100;
    let hx: i32 = tx + hi * tw / 100;
    host::display::fill_rect(lx, ty, hx - lx, 4, 0x00c8ff);
    host::display::fill_rect(lx - 5, ty - 9, 10, 22, 0xffffff);
    host::display::fill_rect(hx - 5, ty - 9, 10, 22, 0xffffff);
    host::display::draw_string(tx, 60, "MIN", 0x808080, 1);
    host::display::draw_number(tx, 74, lo, 0xffffff, 2);
    host::display::draw_string(tx + 90, 60, "MAX", 0x808080, 1);
    host::display::draw_number(tx + 90, 74, hi, 0xffffff, 2);
    host::display::present();
}
